namespace SdlcDashboard.Api.Security;
public sealed class TenantAuthMiddleware(RequestDelegate next,IConfiguration cfg){ public async Task InvokeAsync(HttpContext c){ if(c.Request.Path.StartsWithSegments("/api")){ var key=c.Request.Headers["X-Api-Key"].FirstOrDefault(); var tenant=c.Request.Headers["X-Tenant-Id"].FirstOrDefault(); var expected=cfg["Auth:ApiKey"]; if(string.IsNullOrWhiteSpace(key)||string.IsNullOrWhiteSpace(tenant)||(expected is not null&&!CryptographicEquals(key,expected))){c.Response.StatusCode=401;return;} c.Items["tenant"]=tenant; } await next(c); } static bool CryptographicEquals(string a,string b)=>System.Security.Cryptography.CryptographicOperations.FixedTimeEquals(System.Text.Encoding.UTF8.GetBytes(a),System.Text.Encoding.UTF8.GetBytes(b)); }
